import {Component, HostBinding, OnInit} from '@angular/core';
import {Router} from '@angular/router';

import {NavController, Platform} from '@ionic/angular';
import {routeAnimation} from '../../../shared';

@Component({
    selector: 'app-fail',
    templateUrl: 'fail.page.html',
    styleUrls: ['fail.page.scss'],
    animations: [    // 路由动画
        routeAnimation
    ]
})
export class FailPage implements OnInit {
    ContentId;
    Barcode;
    message;
    title;
    btnCon;

    constructor(
        private router: Router,
        public navCtrl: NavController,
        private platform: Platform
    ) {
        // 控制app返回按钮
        this.platform.backButton.subscribeWithPriority(10, () => {
            this.routeBack();
        });
    }

    @HostBinding('@routeAnimation') state;   // 路由动画
    ngOnInit() {
    }

    ionViewWillEnter() {
    }

    clean() {
        this.title = '';
        this.message = '';
        this.ContentId = undefined;
        this.Barcode = undefined;
    }

    // 路由返回
    routeBack() {
        if (sessionStorage.getItem('loginUserName') === null || sessionStorage.getItem('loginUserName') === ''){
            this.router.navigate(['/login']);
        } else {
            this.router.navigate(['/tabs/tab1']);
        }
    }
}
